package com.example.fingerprintvoting;

import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.util.Base64;import android.widget.*;import androidx.biometric.BiometricManager;import androidx.biometric.BiometricPrompt;import androidx.core.content.ContextCompat;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;

public class MainActivity extends Activity {
  // IMPORTANT: change this to your hosted HTTPS URL ending with /. For Android Emulator use http://10.0.2.2/online_voting-main/ for local XAMPP.
  private static final String BASE_URL="http://10.0.2.2/online_voting-main/";
  private String email="",mode="login",enrollToken=""; private KeyPair keyPair;
  @Override public void onCreate(Bundle b){super.onCreate(b); TextView t=new TextView(this);t.setText("Online Finger Voting\n\nFingerprint Must Be Required\n\nWaiting for biometric verification...");t.setTextSize(20);t.setPadding(40,80,40,40);setContentView(t); handle(getIntent());}
  @Override protected void onNewIntent(Intent i){super.onNewIntent(i);handle(i);}
  void handle(Intent i){Uri u=i.getData(); if(u!=null && "votingapp".equals(u.getScheme())){mode=u.getHost()==null?"login":u.getPathSegments().get(0);email=u.getQueryParameter("email");enrollToken=u.getQueryParameter("enroll_token");} else {mode="login";} if(email==null)email=""; if(enrollToken==null)enrollToken=""; startFlow();}
  void startFlow(){ if(mode.equals("enroll")) generateKey(); else loadKeyAndChallenge(); }
  void generateKey(){try{KeyPairGenerator g=KeyPairGenerator.getInstance("RSA","AndroidKeyStore"); android.security.keystore.KeyGenParameterSpec s=new android.security.keystore.KeyGenParameterSpec.Builder(alias(),android.security.keystore.KeyProperties.PURPOSE_SIGN).setDigests(android.security.keystore.KeyProperties.DIGEST_SHA256).setSignaturePaddings(android.security.keystore.KeyProperties.SIGNATURE_PADDING_RSA_PKCS1).setUserAuthenticationRequired(true).build();g.initialize(s);keyPair=g.generateKeyPair();requestChallenge();}catch(Exception e){toast(e.toString());}}
  void loadKeyAndChallenge(){try{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(alias())){toast("Fingerprint enrollment is required first.");return;}keyPair=new KeyPair(ks.getCertificate(alias()).getPublicKey(),(PrivateKey)ks.getKey(alias(),null));requestChallenge();}catch(Exception e){toast(e.toString());}}
  String alias(){return "voter_"+email.replaceAll("[^A-Za-z0-9]","_");}
  void requestChallenge(){new Thread(()->{try{String data="mode="+enc(mode)+"&email="+enc(email)+(mode.equals("enroll")?"&enroll_token="+enc(enrollToken):"");String out=post(BASE_URL+"biometric_challenge.php",data);String ch=json(out,"challenge");if(ch==null)throw new Exception(out);runOnUiThread(()->prompt(ch));}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}}).start();}
  void prompt(String challenge){BiometricManager bm=BiometricManager.from(this);if(bm.canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_STRONG)!=BiometricManager.BIOMETRIC_SUCCESS){toast("A strong fingerprint/biometric enrolled on this device is required.");return;}try{Signature cryptoSignature=Signature.getInstance("SHA256withRSA");cryptoSignature.initSign(keyPair.getPrivate());BiometricPrompt p=new BiometricPrompt(this,ContextCompat.getMainExecutor(this),new BiometricPrompt.AuthenticationCallback(){public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){super.onAuthenticationSucceeded(r);try{Signature s=r.getCryptoObject()!=null?r.getCryptoObject().getSignature():null;if(s==null)throw new Exception("Biometric crypto session unavailable.");s.update(hex(challenge));String sig=Base64.encodeToString(s.sign(),Base64.NO_WRAP);String pub=Base64.encodeToString(keyPair.getPublic().getEncoded(),Base64.NO_WRAP);verify(challenge,sig,pub);}catch(Exception e){toast(e.toString());}}});BiometricPrompt.PromptInfo info=new BiometricPrompt.PromptInfo.Builder().setTitle("Fingerprint Required").setSubtitle("Verify your fingerprint to continue").setDescription("Fingerprint Must Be Required to vote").setNegativeButtonText("Cancel").build();p.authenticate(info,new BiometricPrompt.CryptoObject(cryptoSignature));}catch(Exception e){toast(e.toString());}}
  void verify(String ch,String sig,String pub){new Thread(()->{try{String data="mode="+enc(mode)+"&email="+enc(email)+"&challenge="+enc(ch)+"&signature="+enc(sig)+"&public_key="+enc(pub)+(mode.equals("enroll")?"&enroll_token="+enc(enrollToken):"");String out=post(BASE_URL+"biometric_verify.php",data);String tok=json(out,"token");if(tok==null)throw new Exception(out);runOnUiThread(()->{toast("Fingerprint verified successfully.");startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(BASE_URL+"biometric_login.php?token="+tok)));});}catch(Exception e){runOnUiThread(()->toast(e.getMessage()));}}).start();}
  static byte[] hex(String s){int n=s.length();byte[] b=new byte[n/2];for(int i=0;i<n;i+=2)b[i/2]=(byte)Integer.parseInt(s.substring(i,i+2),16);return b;}
  static String post(String url,String data)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");c.getOutputStream().write(data.getBytes(StandardCharsets.UTF_8));InputStream in=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);return out.toString("UTF-8");}
  static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
  static String json(String s,String k){String p="\""+k+"\"\s*:\s*\"([^\"]+)";java.util.regex.Matcher m=java.util.regex.Pattern.compile(p).matcher(s);return m.find()?m.group(1):null;}
  void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
